// @generated by:gauntlet run:godseye-local-database
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type DatabaseFixture, databaseFixture, databaseState } from "./pg-helpers.js";

describe("database effects, reconciliation and lifecycle uncertainty", () => {
  let fixture: DatabaseFixture;
  beforeEach(async () => {
    fixture = await databaseFixture();
  });
  afterEach(async () => fixture.store.close());

  it("T-AC-32 reconciles a lost provision acknowledgment after controller reconstruction without repeating effects", async () => {
    fixture.provider.lostAcknowledgments.add("provision");
    const { allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("lost-database-receipt-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "unknown" });
    const effects = structuredClone(fixture.provider.effects),
      physical = structuredClone(fixture.provider.resources.get(allocation.id));
    const restarted = new InfrastructureEngine(fixture.store, fixture.configuration);
    await restarted.foundation.reconcile(fixture.freshOwner(), allocation.runId, randomUUID());
    expect(
      (await restarted.database.overview(fixture.freshOwner())).allocations.find(
        (item) => item.id === allocation.id,
      ),
    ).toMatchObject({ state: "ready" });
    expect(fixture.provider.effects).toEqual(effects);
    expect(fixture.provider.resources.get(allocation.id)).toEqual(physical);
  });

  it.each([
    "scope",
    "system",
    "profile",
    "data-volume",
    "wal-volume",
    "quota",
    "network",
    "policy",
    "evidence",
  ] as const)(
    "T-AC-32 quarantines %s mismatch without adopting, replacing or erasing another cluster",
    async (mode) => {
      const { allocation } = await fixture.admit();
      fixture.provider.inspectResult = (result) => {
        if (mode === "scope")
          return { ...result, scope: { ...result.scope, environmentId: fixture.production.id } };
        if (mode === "system") return { ...result, systemIdentifier: "invalid-system-identity" };
        if (mode === "profile") return { ...result, configurationHash: "f".repeat(64) };
        if (mode === "data-volume") return { ...result, dataVolume: "foreign-data-volume" };
        if (mode === "wal-volume") return { ...result, walVolume: result.dataVolume };
        if (mode === "quota") return { ...result, quotaEnforced: false };
        if (mode === "network") return { ...result, privateNetwork: false };
        if (mode === "policy") return { ...result, policyVerified: false };
        return { ...result, evidence: " " };
      };
      await fixture.infrastructure.foundation.tick("database-inspection-drift-worker");
      expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "quarantined" });
      expect(fixture.provider.effects).toEqual([
        { action: "provision", allocationId: allocation.id },
      ]);
      expect(fixture.provider.resources.has(allocation.id)).toBe(true);
      const other = await fixture.prepare();
      await expect(
        fixture.infrastructure.database.admit(
          fixture.freshOwner(),
          { preparationId: other.id, expectedHash: other.hash, intent: "provision" },
          randomUUID(),
        ),
      ).rejects.toMatchObject({ status: 409 });
    },
  );

  it("T-AC-32 preserves reservations when provider absence cannot prove an uncertain effect is undone", async () => {
    fixture.provider.beforeAction = async (action) => {
      if (action === "provision") throw new Error("Fixture disconnected before receipt");
    };
    const { allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-disconnected-worker");
    fixture.provider.beforeAction = undefined;
    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      allocation.runId,
      randomUUID(),
    );
    expect(["unknown", "quarantined"]).toContain(
      (await databaseState(fixture, allocation.id)).state,
    );
    expect(fixture.provider.effects).toEqual([]);
    const next = await fixture.prepare();
    await expect(
      fixture.infrastructure.database.admit(
        fixture.freshOwner(),
        { preparationId: next.id, expectedHash: next.hash, intent: "provision" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-32 fences a cancelled provider dispatch after an awaited pause without touching another environment", async () => {
    const other = await fixture.admit(fixture.production.id);
    await fixture.infrastructure.foundation.tick("other-database-worker");
    const { allocation } = await fixture.admit();
    fixture.provider.beforeAction = async (action, scope) => {
      if (action === "provision" && scope?.allocationId === allocation.id)
        await fixture.infrastructure.foundation.cancel(
          fixture.freshOwner(),
          allocation.runId,
          randomUUID(),
        );
    };
    await fixture.infrastructure.foundation.tick("cancel-database-dispatch-worker");
    expect(fixture.provider.resources.has(allocation.id)).toBe(false);
    expect(fixture.provider.resources.get(other.allocation.id)?.running).toBe(true);
    expect((await databaseState(fixture, allocation.id)).state).not.toBe("ready");
    expect(
      fixture.provider.effects.filter((effect) => effect.allocationId === allocation.id),
    ).toEqual([]);
  });

  it("T-AC-32 rechecks provider generation after awaited qualification and dispatch", async () => {
    const { allocation } = await fixture.admit();
    fixture.provider.beforeAction = async (action) => {
      if (action === "provision") fixture.provider.binding.generation = "replacement-generation";
    };
    await fixture.infrastructure.foundation.tick("database-provider-change-worker");
    expect(fixture.provider.effects).toEqual([]);
    expect((await databaseState(fixture, allocation.id)).state).not.toBe("ready");
  });

  it("T-AC-32 consumes one durable database run under concurrent scheduler ticks", async () => {
    const { allocation } = await fixture.admit();
    await Promise.all([
      fixture.infrastructure.foundation.tick("database-worker-a"),
      fixture.infrastructure.foundation.tick("database-worker-b"),
    ]);
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "ready" });
    expect(fixture.provider.effects).toEqual([
      { action: "provision", allocationId: allocation.id },
    ]);
  });

  it("T-AC-27 T-AC-32 suspends and resumes only verified exact cells while keeping requested and actual state distinct", async () => {
    const { preparation, allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-initial-worker");
    const identity = fixture.provider.resources.get(allocation.id)?.systemIdentifier;
    const suspended = await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: preparation.id, expectedHash: preparation.hash, intent: "suspend" },
      randomUUID(),
    );
    expect(suspended).toMatchObject({
      id: allocation.id,
      state: "ready",
      requestedState: "suspended",
      generation: 2,
    });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(true);
    await fixture.infrastructure.foundation.tick("database-suspend-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({
      state: "suspended",
      requestedState: "suspended",
    });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
    const resumed = await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: preparation.id, expectedHash: preparation.hash, intent: "resume" },
      randomUUID(),
    );
    expect(resumed).toMatchObject({ state: "suspended", requestedState: "ready", generation: 3 });
    await fixture.infrastructure.foundation.tick("database-resume-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({
      state: "ready",
      requestedState: "ready",
    });
    expect(fixture.provider.resources.get(allocation.id)?.systemIdentifier).toBe(identity);
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual([
      "provision",
      "suspend",
      "resume",
    ]);
  });

  it("T-AC-32 reconciles lost suspend acknowledgment without recreating or repeating the stop", async () => {
    const { preparation, allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-before-suspend-worker");
    fixture.provider.lostAcknowledgments.add("suspend");
    const pending = await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: preparation.id, expectedHash: preparation.hash, intent: "suspend" },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("database-lost-suspend-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "unknown" });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
    const effects = structuredClone(fixture.provider.effects);
    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      pending.runId,
      randomUUID(),
    );
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "suspended" });
    expect(fixture.provider.effects).toEqual(effects);
  });

  it("T-AC-32 refuses a substituted system identity before suspension without stopping the replacement", async () => {
    const { preparation, allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-before-substitution-worker");
    const resource = fixture.provider.resources.get(allocation.id);
    if (!resource) throw new Error("Fixture resource missing");
    resource.systemIdentifier = `${resource.systemIdentifier}1`;
    await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: preparation.id, expectedHash: preparation.hash, intent: "suspend" },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("database-replaced-cluster-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "quarantined" });
    expect(resource.running).toBe(true);
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual(["provision"]);
  });
  it("T-AC-31 redacts unexpected provider exception material from owner-visible metadata and audit", async () => {
    const marker = randomUUID();
    fixture.provider.beforeAction = async (action) => {
      if (action === "provision") throw new Error(`postgresql://private/${marker}`);
    };
    const { allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-private-error-worker");
    expect((await databaseState(fixture, allocation.id)).state).not.toBe("ready");
    const visible = JSON.stringify({
      databases: await fixture.infrastructure.database.overview(fixture.freshOwner()),
      audit: await fixture.core.listAudit(fixture.freshOwner()),
      operation: await fixture.infrastructure.foundation.getRun(
        fixture.freshOwner(),
        allocation.runId,
      ),
    });
    expect(visible).not.toContain(marker);
    expect(visible).not.toContain("postgresql://private");
  });
});
